import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

// Shared field styles keep standalone inputs and segmented date/time controls in sync.
export const fieldLabelStyles = "text-sm font-medium text-foreground";
export const fieldDescriptionStyles = "text-xs leading-5 text-muted-foreground";
export const fieldErrorStyles = "text-xs leading-5 text-destructive";

export const fieldInputStyles =
  "min-h-12 w-full cursor-text rounded-lg border border-input bg-card text-base text-foreground shadow-[var(--shadow-card)] outline-none placeholder:text-muted-foreground/80 hover:border-primary/45 data-[focus-visible]:border-ring data-[focus-visible]:ring-3 data-[focus-visible]:ring-ring/50 data-[invalid]:border-destructive data-[invalid]:ring-3 data-[invalid]:ring-destructive/20 data-[invalid]:hover:border-destructive data-[invalid]:data-[focus-visible]:border-destructive data-[invalid]:data-[focus-visible]:ring-destructive/30 read-only:bg-muted/40 read-only:hover:border-input data-[disabled]:cursor-not-allowed data-[disabled]:bg-muted data-[disabled]:opacity-60 data-[disabled]:hover:border-input sm:text-sm";

export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] hover:border-primary/45 has-[[data-focus-visible]]:border-ring has-[[data-focus-visible]]:ring-3 has-[[data-focus-visible]]:ring-ring/50 group-data-[invalid]:border-destructive group-data-[invalid]:hover:border-destructive group-data-[invalid]:has-[[data-focus-visible]]:border-destructive group-data-[invalid]:has-[[data-focus-visible]]:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-data-[disabled]:bg-muted group-data-[disabled]:opacity-60 group-data-[disabled]:hover:border-input";

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  composeRenderProps,
  type ListBoxItemProps,
  type ListBoxProps,
} from "react-aria-components";
import { Check } from "reicon-react";
import { cn } from "./utils";

export function ListBox<T extends object>({
  className,
  ...props
}: ListBoxProps<T>) {
  return (
    <AriaListBox
      {...props}
      data-slot="list-box"
      className={composeRenderProps(className, (className) =>
        cn(
          "grid max-h-72 w-full gap-1 overflow-y-auto rounded-lg border border-border bg-card p-1.5 shadow-[var(--shadow-card)] outline-none",
          className,
        ),
      )}
    />
  );
}

export function ListBoxItem({
  className,
  children,
  ...props
}: ListBoxItemProps) {
  return (
    <AriaListBoxItem
      {...props}
      data-slot="list-box-item"
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-3 text-sm text-foreground outline-none hover:bg-muted data-[focused]:bg-muted data-[selected]:bg-accent data-[selected]:text-accent-foreground data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-[-2px] data-[focus-visible]:outline-ring",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {content}
          <SelectionMark isSelected={isSelected} />
        </>
      ))}
    </AriaListBoxItem>
  );
}

/** Keep the check in the layout when an option is not selected. */
export function SelectionMark({
  isSelected,
  className,
}: {
  isSelected: boolean;
  className?: string;
}) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.span
      aria-hidden="true"
      className={cn("ms-auto shrink-0", className)}
      initial={false}
      animate={{ opacity: isSelected ? 1 : 0, scale: isSelected ? 1 : 0.85 }}
      transition={{
        duration: reduceMotion ? 0 : 0.16,
        ease: [0.23, 1, 0.32, 1],
      }}
    >
      <Check size={16} />
    </motion.span>
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  Popover as AriaPopover,
  composeRenderProps,
  type PopoverProps,
} from "react-aria-components";
import { cn } from "./utils";

function edgeOffset(placement: string | null) {
  switch (placement) {
    case "top":
      return { x: 0, y: 5 };
    case "left":
      return { x: 5, y: 0 };
    case "right":
      return { x: -5, y: 0 };
    default:
      return { x: 0, y: -5 };
  }
}

type StyledPopoverProps = PopoverProps & { "data-slot"?: string };

export function Popover({
  className,
  "data-slot": dataSlot = "popover",
  ...props
}: StyledPopoverProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      render={
        props.render ??
        ((domProps, { placement, isExiting }) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={
              reduceMotion || props.shouldSkipAnimation
                ? false
                : { opacity: 0, ...edgeOffset(placement), scale: 0.98 }
            }
            animate={
              isExiting
                ? {
                    opacity: 0,
                    ...(reduceMotion ? {} : edgeOffset(placement)),
                    scale: reduceMotion ? 1 : 0.99,
                  }
                : { opacity: 1, x: 0, y: 0, scale: 1 }
            }
            transition={{
              duration: reduceMotion ? 0 : isExiting ? 0.14 : 0.2,
              ease: [0.23, 1, 0.32, 1],
            }}
          />
        ))
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] rounded-xl border border-border bg-popover p-5 text-popover-foreground shadow-[var(--shadow-float)] outline-none data-[placement=top]:origin-bottom data-[placement=bottom]:origin-top data-[placement=left]:origin-right data-[placement=right]:origin-left",
          className,
        ),
      )}
    />
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { Button, type ButtonProps } from "react-aria-components";

/** React Aria handles presses; Motion supplies the visual feedback. */
export function PressButton({ isDisabled, ...props }: ButtonProps) {
  const reduceMotion = useReducedMotion();

  return (
    <Button
      data-slot="press-button"
      {...props}
      isDisabled={isDisabled}
      render={
        props.render ??
        ((domProps) => (
          <motion.button
            {...(domProps as HTMLMotionProps<"button">)}
            whileTap={reduceMotion || isDisabled ? undefined : { scale: 0.96 }}
            transition={{ type: "spring", stiffness: 500, damping: 36 }}
          />
        ))
      }
    />
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { type ReactNode, useContext } from "react";
import {
  type Button as AriaButton,
  Select as AriaSelect,
  type SelectProps as AriaSelectProps,
  SelectValue as AriaSelectValue,
  composeRenderProps,
  FieldError,
  Label,
  ListBox,
  ListBoxItem,
  SelectStateContext,
  Text,
} from "react-aria-components";
import { ChevronDown } from "reicon-react";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldLabelStyles,
} from "./field-styles";
import { SelectionMark } from "./list-box";
import { Popover } from "./popover";
import { PressButton } from "./press-button";

const selectTriggerStyles =
  "flex min-h-12 w-full cursor-pointer items-center justify-between gap-3 rounded-lg border border-input bg-card px-3.5 text-start text-sm text-foreground shadow-[var(--shadow-card)] hover:border-primary/45 hover:bg-muted/60 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring group-data-[invalid]:border-destructive group-data-[invalid]:ring-3 group-data-[invalid]:ring-destructive/20 data-[disabled]:cursor-default data-[disabled]:bg-muted data-[disabled]:opacity-50";
const selectItemStyles =
  "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-2.5 py-2 text-sm outline-none hover:bg-muted data-[focused]:bg-muted data-[selected]:bg-accent data-[selected]:text-accent-foreground data-[focus-visible]:-outline-offset-2 data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring data-[disabled]:cursor-default data-[disabled]:opacity-50";
const selectPopoverStyles =
  "w-[var(--trigger-width)] rounded-lg border-0 p-1.5 ring-1 ring-border/70";

export interface SelectOption {
  id: string;
  name: string;
  description?: string;
}
export interface SelectProps
  extends Omit<AriaSelectProps<SelectOption>, "children" | "className"> {
  label?: string;
  description?: string;
  options?: SelectOption[];
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaSelectProps<SelectOption>["className"];
  children?: AriaSelectProps<SelectOption>["children"];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export function Select({
  label,
  description,
  options,
  className,
  children,
  value,
  defaultValue,
  onValueChange,
  placeholder = "Select an option",
  ...props
}: SelectProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaSelect
      {...props}
      data-slot="select"
      selectedKey={value ?? props.selectedKey}
      defaultSelectedKey={defaultValue ?? props.defaultSelectedKey}
      onSelectionChange={(key) => {
        props.onSelectionChange?.(key);
        onValueChange?.(key === null ? "" : String(key));
      }}
      placeholder={placeholder}
      className={composeRenderProps(className, (className) =>
        cn("group flex w-full flex-col gap-2", className),
      )}
    >
      {children ??
        (({ isOpen }) => (
          <>
            {label && (
              <Label data-slot="select-label" className={fieldLabelStyles}>
                {label}
              </Label>
            )}
            <PressButton
              data-slot="select-trigger"
              className={selectTriggerStyles}
            >
              <AriaSelectValue
                data-slot="select-value"
                className="min-w-0 flex-1 truncate text-start data-[placeholder]:text-muted-foreground"
              >
                {({ selectedText, isPlaceholder, state }) =>
                  isPlaceholder
                    ? placeholder
                    : (options?.find(
                        (option) => option.id === state.selectedKey,
                      )?.name ?? selectedText)
                }
              </AriaSelectValue>
              <motion.span
                initial={false}
                animate={{ rotate: isOpen ? 180 : 0 }}
                transition={{
                  duration: reduceMotion ? 0 : 0.2,
                  ease: "easeOut",
                }}
                className="shrink-0 text-muted-foreground"
              >
                <ChevronDown size={16} aria-hidden="true" />
              </motion.span>
            </PressButton>
            {description && (
              <Text
                slot="description"
                data-slot="select-description"
                className={fieldDescriptionStyles}
              >
                {description}
              </Text>
            )}
            <SelectError />
            <Popover
              data-slot="select-content"
              placement="bottom start"
              offset={7}
              className={selectPopoverStyles}
            >
              <ListBox
                data-slot="select-list-box"
                items={options ?? []}
                className="grid max-h-64 gap-1 overflow-y-auto outline-none"
              >
                {(option) => (
                  <ListBoxItem
                    data-slot="select-item"
                    id={option.id}
                    textValue={option.name}
                    className={selectItemStyles}
                  >
                    {({ isSelected }) => (
                      <>
                        <span className="min-w-0">
                          <span className="block font-medium">
                            {option.name}
                          </span>
                          {option.description && (
                            <span className="mt-0.5 block text-xs text-muted-foreground group-data-[selected]/item:text-accent-foreground">
                              {option.description}
                            </span>
                          )}
                        </span>
                        <SelectionMark isSelected={isSelected} />
                      </>
                    )}
                  </ListBoxItem>
                )}
              </ListBox>
            </Popover>
          </>
        ))}
    </AriaSelect>
  );
}

export function SelectLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="select-label"
      className={cn(fieldLabelStyles, className)}
    />
  );
}

export function SelectTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AriaButton>) {
  return (
    <PressButton
      {...props}
      data-slot="select-trigger"
      className={composeRenderProps(className, (className) =>
        cn(selectTriggerStyles, className),
      )}
    >
      {children ?? (
        <>
          <SelectValue />
          <SelectChevron />
        </>
      )}
    </PressButton>
  );
}

function SelectChevron() {
  const isOpen = useContext(SelectStateContext)?.isOpen;
  const reduceMotion = useReducedMotion();
  return (
    <motion.span
      aria-hidden="true"
      className="shrink-0 text-muted-foreground"
      initial={false}
      animate={{ rotate: isOpen ? 180 : 0 }}
      transition={{ duration: reduceMotion ? 0 : 0.2, ease: "easeOut" }}
    >
      <ChevronDown size={16} />
    </motion.span>
  );
}

export function SelectValue({
  className,
  ...props
}: React.ComponentProps<typeof AriaSelectValue>) {
  return (
    <AriaSelectValue
      {...props}
      data-slot="select-value"
      className={composeRenderProps(className, (className) =>
        cn(
          "min-w-0 flex-1 truncate text-start data-[placeholder]:text-muted-foreground",
          className,
        ),
      )}
    >
      {props.children ??
        (({ selectedText, defaultChildren }) =>
          selectedText || defaultChildren)}
    </AriaSelectValue>
  );
}

export function SelectContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  return (
    <Popover
      {...props}
      data-slot="select-content"
      placement={props.placement ?? "bottom start"}
      offset={props.offset ?? 7}
      className={composeRenderProps(className, (className) =>
        cn(selectPopoverStyles, className),
      )}
    >
      <ListBox
        data-slot="select-list-box"
        className="grid max-h-64 gap-1 overflow-y-auto outline-none"
      >
        {children}
      </ListBox>
    </Popover>
  );
}

export function SelectItem({
  className,
  children,
  ...props
}: Omit<React.ComponentProps<typeof ListBoxItem>, "children"> & {
  children: ReactNode;
}) {
  return (
    <ListBoxItem
      {...props}
      data-slot="select-item"
      className={composeRenderProps(className, (className) =>
        cn(selectItemStyles, className),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {content}
          <SelectionMark isSelected={isSelected} />
        </>
      ))}
    </ListBoxItem>
  );
}

export function SelectError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="select-error"
      className={cn(fieldErrorStyles, className)}
    />
  );
}

export function SelectDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="select-description"
      className={cn(fieldDescriptionStyles, className)}
    />
  );
}
